def transform(grid):
    # Horizontal and vertical 2-lines divide the noisy canvas into panels.
    # A panel is positive when its two foreground marks occur in different
    # rows and different columns; a lone mark or an aligned pair is negative.
    h, w = len(grid), len(grid[0])
    row_bands, col_bands = [], []
    start = 0
    for r in range(h):
        if all(v == 2 for v in grid[r]):
            if start < r:
                row_bands.append((start, r))
            start = r + 1
    if start < h:
        row_bands.append((start, h))
    start = 0
    for c in range(w):
        if all(grid[r][c] == 2 for r in range(h)):
            if start < c:
                col_bands.append((start, c))
            start = c + 1
    if start < w:
        col_bands.append((start, w))
    result = []
    for r0, r1 in row_bands:
        row = []
        for c0, c1 in col_bands:
            pts = [(r, c) for r in range(r0, r1) for c in range(c0, c1)
                   if grid[r][c] not in (2, 4, 9)]
            positive = (len(pts) == 2 and pts[0][0] != pts[1][0]
                        and pts[0][1] != pts[1][1])
            row.append(1 if positive else 9)
        result.append(row)
    return result

