def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Find straight monochrome bars. A bar is (color, orientation, fixed, lo, hi).
    bars = []
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == bg:
                c += 1
                continue
            color, lo = grid[r][c], c
            while c < w and grid[r][c] == color:
                c += 1
            if c - lo >= 2:
                bars.append((color, 'h', r, lo, c - 1))
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] == bg:
                r += 1
                continue
            color, lo = grid[r][c], r
            while r < h and grid[r][c] == color:
                r += 1
            if r - lo >= 2:
                bars.append((color, 'v', c, lo, r - 1))

    # Two equal-length, same-color, parallel bars are the guide rails.
    pairs = []
    for i, a in enumerate(bars):
        for b in bars[i + 1:]:
            if (a[0] == b[0] and a[1] == b[1] and a[2] != b[2]
                    and a[4] - a[3] == b[4] - b[3]):
                pairs.append((abs(a[2] - b[2]), a, b))
    if not pairs:
        return out
    _, a, b = max(pairs, key=lambda z: z[0])
    rail_color, orient = a[0], a[1]

    # Non-rail foreground singletons are projected from the rail whose span
    # contains their along-rail coordinate: ray to that rail, then a matching
    # crossbar at the same relative offset on the opposite rail.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or color == rail_color:
                continue
            along = c if orient == 'h' else r
            across = r if orient == 'h' else c
            options = [(x, y) for x, y in ((a, b), (b, a))
                       if x[3] <= along <= x[4]]
            if not options:
                continue
            source, target = min(options, key=lambda pair: abs(across - pair[0][2]))
            source_fixed, target_fixed = source[2], target[2]
            out[r][c] = 4

            # Continue from the marker toward its source rail in marker color.
            step = 1 if source_fixed > across else -1
            p = across + step
            while p != source_fixed:
                rr, cc = (p, c) if orient == 'h' else (r, p)
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                    out[rr][cc] = color
                p += step

            # Project the marker's rail-relative position across the gap.
            projected = target[3] + (along - source[3])
            step = 1 if target_fixed > source_fixed else -1
            p = source_fixed + step
            while True:
                rr, cc = (p, projected) if orient == 'h' else (projected, p)
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                    out[rr][cc] = color
                if p == target_fixed:
                    break
                p += step
    return out

