from collections import Counter

def transform(grid):
    """Retain near-solid rectangular color objects; erase isolated noise."""
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = {v for row in grid for v in row if v != bg}
    boxes = []
    for color in colors:
        # Enumerate plausible rectangles. Corrupt cells may be any other color,
        # but genuine rectangles retain at least 80% of their cells per row,
        # per column, and overall.
        for r0 in range(h - 1):
            for r1 in range(r0 + 1, h):
                height = r1 - r0 + 1
                for c0 in range(w - 1):
                    for c1 in range(c0 + 1, w):
                        width = c1 - c0 + 1
                        area = height * width
                        count = sum(grid[r][c] == color
                                    for r in range(r0, r1 + 1)
                                    for c in range(c0, c1 + 1))
                        if count / area < 0.80:
                            continue
                        if any(sum(grid[r][c] == color for c in range(c0, c1 + 1)) / width < 0.80
                               for r in range(r0, r1 + 1)):
                            continue
                        if any(sum(grid[r][c] == color for r in range(r0, r1 + 1)) / height < 0.80
                               for c in range(c0, c1 + 1)):
                            continue
                        boxes.append((color, r0, r1, c0, c1, count, area))
    # Consider largest candidate first; smaller heavily-overlapping candidates
    # are merely fragments of a noisy rectangle already selected.
    boxes.sort(key=lambda b: (b[6], b[5]), reverse=True)
    selected = []
    for box in boxes:
        color, r0, r1, c0, c1, count, area = box
        if any(color == old[0] and
               max(0, min(r1, old[2]) - max(r0, old[1]) + 1) *
               max(0, min(c1, old[4]) - max(c0, old[3]) + 1) >= 0.8 * min(area, old[6])
               for old in selected):
            continue
        selected.append(box)
    out = [[bg] * w for _ in range(h)]
    for color, r0, r1, c0, c1, _, _ in selected:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                out[r][c] = color
    return out

