from collections import Counter


def transform(grid):
    """Keep and repair noisy, mostly-solid rectangular color objects."""
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = set(v for row in grid for v in row if v != background)
    candidates = []

    # Search complete bounding rectangles rather than connected components:
    # corruption can split an object into multiple same-color components.
    for color in colors:
        for r0 in range(h):
            for r1 in range(r0 + 1, h):
                rh = r1 - r0 + 1
                for c0 in range(w):
                    for c1 in range(c0 + 1, w):
                        cw = c1 - c0 + 1
                        area = rh * cw
                        if area < 4:
                            continue
                        count = sum(grid[r][c] == color
                                    for r in range(r0, r1 + 1)
                                    for c in range(c0, c1 + 1))
                        if count < 4 or count / area < 0.78:
                            continue
                        # Do not bridge two objects across a wholly empty row/column.
                        if any(sum(grid[r][c] == color for c in range(c0, c1 + 1)) < cw * 0.5
                               for r in range(r0, r1 + 1)):
                            continue
                        if any(sum(grid[r][c] == color for r in range(r0, r1 + 1)) < rh * 0.5
                               for c in range(c0, c1 + 1)):
                            continue
                        candidates.append((area, count / area, color, r0, r1, c0, c1))

    candidates.sort(reverse=True)
    chosen = []
    occupied = [[False] * w for _ in range(h)]
    for area, density, color, r0, r1, c0, c1 in candidates:
        if any(occupied[r][c] for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)):
            continue
        chosen.append((color, r0, r1, c0, c1))
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                occupied[r][c] = True

    out = [[background] * w for _ in range(h)]
    for color, r0, r1, c0, c1 in chosen:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                out[r][c] = color
    return out


