def transform(grid):
    """Move the patterned non-divider cells up to the full 2-line and mark the vacated side with 8."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    # The 2 divider is a full row or full column.
    divider = None
    axis = None
    for r in range(h):
        if all(grid[r][c] == 2 for c in range(w)):
            divider, axis = r, 'h'
            break
    if divider is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                divider, axis = c, 'v'
                break
    if divider is None:
        return out
    pts = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] != bg and grid[r][c] != 2]
    if not pts:
        return out
    if axis == 'h':
        lo, hi = min(r for r, c in pts), max(r for r, c in pts)
        # Pack the pattern against the divider, retaining its exact internal shape.
        delta = (divider + 1 - lo) if hi < divider else (divider - 1 - hi)
        # Clear old motif cells, then translate all colored pixels.
        for r, c in pts:
            out[r][c] = bg
        for r, c in pts:
            nr = r + delta
            if 0 <= nr < h:
                out[nr][c] = grid[r][c]
        near = lo + delta
        line = near - 1 if near > divider else near + 1
        if 0 <= line < h and line != divider:
            out[line] = [8] * w
    else:
        lo, hi = min(c for r, c in pts), max(c for r, c in pts)
        delta = (divider + 1 - lo) if hi < divider else (divider - 1 - hi)
        for r, c in pts:
            out[r][c] = bg
        for r, c in pts:
            nc = c + delta
            if 0 <= nc < w:
                out[r][nc] = grid[r][c]
        near = lo + delta
        line = near - 1 if near > divider else near + 1
        if 0 <= line < w and line != divider:
            for r in range(h):
                out[r][line] = 8
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))

