def transform(grid):
    """Decode a compact array stored at colored intersections of a tiled grid."""
    h, w = len(grid), len(grid[0])
    palette = set(v for row in grid for v in row)
    best = None

    # Fit the two-color periodic lattice: tiles have a solid interior fill,
    # while their horizontal/vertical boundaries use a framework color.
    for fill, frame in product(palette, repeat=2):
        if fill == frame:
            continue
        for rp in range(2, min(10, h) + 1):
            for ro in range(rp):
                row_lines = [r for r in range(h) if r % rp == ro]
                if len(row_lines) < 2:
                    continue
                for cp in range(2, min(10, w) + 1):
                    for co in range(cp):
                        col_lines = [c for c in range(w) if c % cp == co]
                        if len(col_lines) < 2:
                            continue
                        mismatches = 0
                        for r in range(h):
                            on_row = r % rp == ro
                            for c in range(w):
                                expected = frame if on_row or c % cp == co else fill
                                mismatches += grid[r][c] != expected
                        # Prefer simpler (less frequent boundary) periods only
                        # after minimizing unexplained cells.
                        score = (mismatches, rp + cp, rp, cp, ro, co)
                        if best is None or score < best[0]:
                            best = (score, fill, frame, rp, ro, cp, co)

    if best is None:
        return [row[:] for row in grid]

    _, fill, frame, rp, ro, cp, co = best
    row_lines = [r for r in range(h) if r % rp == ro]
    col_lines = [c for c in range(w) if c % cp == co]

    # Non-fill, non-framework colors at lattice crossings mark the encoded patch.
    marked = [(ri, ci) for ri, r in enumerate(row_lines)
              for ci, c in enumerate(col_lines)
              if grid[r][c] not in (fill, frame)]
    if not marked:
        return [[fill]]
    rmin = min(ri for ri, _ in marked)
    rmax = max(ri for ri, _ in marked)
    cmin = min(ci for _, ci in marked)
    cmax = max(ci for _, ci in marked)

    # Each output cell is the tile enclosed by four marker intersections.
    # Keep a marker color only when all four corners agree; otherwise use fill.
    output = []
    for ri in range(rmin, rmax):
        row = []
        for ci in range(cmin, cmax):
            corners = (grid[row_lines[ri]][col_lines[ci]],
                       grid[row_lines[ri]][col_lines[ci + 1]],
                       grid[row_lines[ri + 1]][col_lines[ci]],
                       grid[row_lines[ri + 1]][col_lines[ci + 1]])
            if corners[0] not in (fill, frame) and all(v == corners[0] for v in corners):
                row.append(corners[0])
            else:
                row.append(fill)
        output.append(row)
    return output


