def transform(grid):
    """In two repeated horizontal bands, mark the shorter row's trailing
    continuation up to the farther endpoint in its corresponding row."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    bands = []
    r = 0
    while r < h:
        if any(v != bg for v in grid[r]):
            start = r
            while r + 1 < h and any(v != bg for v in grid[r + 1]):
                r += 1
            bands.append((start, r))
        r += 1

    for i, (a0, a1) in enumerate(bands):
        height = a1 - a0 + 1
        for b0, b1 in bands[i + 1:]:
            if b1 - b0 + 1 != height:
                continue
            # Repeated copies share foreground at aligned positions.
            overlap = sum(
                1 for k in range(height) for c in range(w)
                if grid[a0 + k][c] != bg and grid[b0 + k][c] != bg
            )
            if not overlap:
                continue
            for k in range(height):
                a_marks = [c for c, v in enumerate(grid[a0 + k]) if v != bg]
                b_marks = [c for c, v in enumerate(grid[b0 + k]) if v != bg]
                if not a_marks or not b_marks:
                    continue
                end = max(a_marks + b_marks)
                for row_index, marks in ((a0 + k, a_marks), (b0 + k, b_marks)):
                    last = max(marks)
                    for c in range(last + 1, end + 1):
                        if grid[row_index][c] == bg:
                            out[row_index][c] = 1
            break
    return out

