        if grid[bot][c]==bg:out[bot][c]=2
    for r in range(top,bot+1):
        if grid[r][left]==bg:out[r][left]=2
        if grid[r][right]==bg:out[r][right]=2
    # Internal broken horizontal/vertical lines of length 2/3 are also completed.
    for r in range(h):
        cs=[c for c in range(w) if grid[r][c]==ink]
        for a,b in zip(cs,cs[1:]):
            if 2<=b-a<=3:
                for c in range(a+1,b):out[r][c]=2
    for c in range(w):
        rs=[r for r in range(h) if grid[r][c]==ink]
        for a,b in zip(rs,rs[1:]):
            if 2<=b-a<=3:
